74	class DeepSeekProvider extends OpenAiChatCompletionProvider {
75	  private originalConfig?: DeepSeekConfig;
76	
77	  protected get apiKey(): string | undefined {
78	    return this.config?.apiKey;
79	  }
80	
81	  constructor(modelName: string, providerOptions: DeepSeekProviderOptions) {
82	    // Extract the nested config
83	    const deepseekConfig = providerOptions.config?.config;
84	
85	    super(modelName, {
86	      ...providerOptions,
87	      config: {
88	        ...providerOptions.config,
89	        ...deepseekConfig,
90	        apiKeyEnvar: 'DEEPSEEK_API_KEY',
91	        apiBaseUrl: 'https://api.deepseek.com/v1',
92	      },
93	    });
94	
95	    this.originalConfig = deepseekConfig;
96	  }
97	
98	  id(): string {
99	    return `deepseek:${this.modelName}`;
100	  }
101	
102	  toString(): string {
103	    return `[DeepSeek Provider ${this.modelName}]`;
104	  }
105	
106	  toJSON() {
107	    return {
108	      provider: 'deepseek',
109	      model: this.modelName,
110	      config: {
111	        ...this.config,
112	        ...(this.apiKey && { apiKey: undefined }),
113	      },
114	    };
115	  }
116	
117	  async callApi(prompt: string, context?: any, callApiOptions?: any): Promise<any> {
118	    const response = await super.callApi(prompt, context, callApiOptions);
119	
120	    if (!response || response.error) {
121	      return response;
122	    }
123	
124	    // Extract cache hit information if available
125	    let cachedTokens = 0;
126	    if (typeof response.raw === 'string') {
127	      try {
128	        const rawData = JSON.parse(response.raw);
129	        if (rawData?.usage?.prompt_tokens_details?.cached_tokens) {
130	          cachedTokens = rawData.usage.prompt_tokens_details.cached_tokens;
131	        }
132	      } catch (err) {
133	        logger.debug(`Failed to parse raw response for cache info: ${err}`);
134	      }
135	    } else if (typeof response.raw === 'object' && response.raw !== null) {
136	      const rawData = response.raw;
137	      if (rawData?.usage?.prompt_tokens_details?.cached_tokens) {
138	        cachedTokens = rawData.usage.prompt_tokens_details.cached_tokens;
139	      }
140	    }
141	
142	    // Calculate cost with cache information
143	    if (response.tokenUsage && !response.cached) {
144	      response.cost = calculateDeepSeekCost(
145	        this.modelName,
146	        this.config || {},
147	        response.tokenUsage.prompt,
148	        response.tokenUsage.completion,
149	        cachedTokens,
150	      );
151	    }
152	
153	    return response;
154	  }
155	}
