import { getEnvString } from '../envars';
import logger from '../logger';
import { parseChatPrompt, REQUEST_TIMEOUT_MS } from './shared';

import type { EnvVarKey } from '../envars';
import type { EnvOverrides } from '../types/env';
import type {
  ApiProvider,
  CallApiContextParams,
  CallApiOptionsParams,
  ProviderOptions,
  ProviderResponse,
} from '../types/index';

const ABLITERATION_API_BASE_URL = 'https://api.abliteration.ai/v1';
const ABLITERATION_API_KEY_ENVAR = 'ABLIT_KEY';

interface AbliterationConfig {
  apiBaseUrl: string;
  apiKey?: string;
  apiKeyEnvar: string;
  showThinking: boolean;
  [key: string]: any;
}

/**
 * Returns the first value that is neither undefined/null nor an empty string.
 * Empty strings are treated as unset so they fall through to the next candidate.
 */
function firstNonEmpty(...values: Array<string | undefined>): string | undefined {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== '') {
      return value;
    }
  }
  return undefined;
}

/**
 * Provider for the Abliteration AI service. Speaks the OpenAI-compatible
 * chat completions API but manages its own authentication and configuration
 * (it never falls back to OpenAI credentials or the OpenAI-Organization header).
 */
export class AbliterationProvider implements ApiProvider {
  modelName: string;
  config: AbliterationConfig;
  env?: EnvOverrides;

  constructor(modelName: string, options: ProviderOptions = {}) {
    const { config, env } = options;
    this.modelName = modelName;
    this.env = env;

    const providedConfig = (config ?? {}) as Partial<AbliterationConfig>;

    // Resolve the API base URL following the documented priority order:
    // (1) config.apiBaseUrl, (2) env override, (3) process env, (4) default.
    const apiBaseUrl =
      firstNonEmpty(
        providedConfig.apiBaseUrl,
        env?.ABLIT_API_BASE_URL,
        getEnvString('ABLIT_API_BASE_URL'),
      ) ?? ABLITERATION_API_BASE_URL;

    this.config = {
      ...providedConfig,
      apiBaseUrl,
      apiKeyEnvar: providedConfig.apiKeyEnvar || ABLITERATION_API_KEY_ENVAR,
      showThinking: providedConfig.showThinking ?? false,
    };
  }

  id(): string {
    return `abliteration:${this.modelName}`;
  }

  toString(): string {
    return `[Abliteration Provider ${this.modelName}]`;
  }

  toJSON() {
    return {
      provider: 'abliteration',
      model: this.modelName,
      config: {
        ...this.config,
        // Redact the API key from JSON output regardless of how it was provided.
        apiKey: undefined,
      },
    };
  }

  getApiKey(): string | undefined {
    const envar = this.config.apiKeyEnvar;
    return (
      this.config.apiKey ||
      this.env?.[envar as keyof EnvOverrides] ||
      getEnvString(envar as EnvVarKey)
    );
  }

  getOrganization(): undefined {
    return undefined;
  }

  private getMissingApiKeyErrorMessage(): string {
    return `API key is not set. Set the ${this.config.apiKeyEnvar} environment variable or add \`apiKey\` to the provider config.`;
  }

  async callApi(
    prompt: string,
    context?: CallApiContextParams,
    callApiOptions?: CallApiOptionsParams,
  ): Promise<ProviderResponse> {
    const apiKey = this.getApiKey();
    if (!apiKey) {
      throw new Error(this.getMissingApiKeyErrorMessage());
    }

    const config = {
      ...this.config,
      ...context?.prompt?.config,
    };

    const messages = parseChatPrompt(prompt, [{ role: 'user', content: prompt }]);

    const body = {
      model: this.modelName,
      messages,
      ...(config.temperature === undefined ? {} : { temperature: config.temperature }),
      ...(config.max_tokens === undefined ? {} : { max_tokens: config.max_tokens }),
      ...(config.top_p === undefined ? {} : { top_p: config.top_p }),
      ...(config.stop ? { stop: config.stop } : {}),
      ...(config.passthrough || {}),
    };

    const url = `${this.config.apiBaseUrl}/chat/completions`;

    logger.debug(`Calling Abliteration API`, { url, body });

    let data: any;
    let status: number;
    let statusText: string;
    let cached = false;
    let latencyMs: number | undefined;
    let responseHeaders: Record<string, string> | undefined;
    let deleteFromCache: (() => Promise<void>) | undefined;

    try {
      ({
        data,
        cached,
        status,
        statusText,
        latencyMs,
        deleteFromCache,
        headers: responseHeaders,
      } = await fetchWithCache(
        url,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${apiKey}`,
            ...config.headers,
          },
          body: JSON.stringify(body),
        },
        REQUEST_TIMEOUT_MS,
        'json',
        context?.bustCache ?? context?.debug,
        this.config.maxRetries,
      ));
    } catch (err) {
      await deleteFromCache?.();
      logger.error(`Abliteration API call error: ${String(err)}`);
      return { error: `API call error: ${String(err)}` };
    }

    if (status < 200 || status >= 300) {
      return {
        error: `API error: ${status} ${statusText}`,
        metadata: {
          http: {
            status,
            ...(responseHeaders ? { headers: responseHeaders } : {}),
          },
        },
      } as ProviderResponse;
    }

    try {
      const message = data.choices?.[0]?.message ?? {};
      const content = message.content ?? '';

      let output: string = content;
      if (
        message.reasoning_content &&
        typeof message.reasoning_content === 'string' &&
        this.config.showThinking
      ) {
        output = `Thinking: ${message.reasoning_content}\n\n${content}`;
      }

      const usage = data.usage;
      const tokenUsage = usage
        ? cached
          ? { cached: usage.total_tokens, total: usage.total_tokens }
          : {
              total: usage.total_tokens,
              prompt: usage.prompt_tokens || 0,
              completion: usage.completion_tokens || 0,
              numRequests: 1,
            }
        : { numRequests: cached ? 0 : 1 };

      return {
        output,
        tokenUsage,
        cached,
        ...(latencyMs === undefined ? {} : { latencyMs }),
      };
    } catch (err) {
      await deleteFromCache?.();
      return {
        error: `API error: ${String(err)}: ${JSON.stringify(data)}`,
      };
    }
  }
}

/**
 * Factory that parses an `abliteration:<model_name>` or
 * `abliteration:chat:<model_name>` path and returns an AbliterationProvider.
 * The `chat:` segment is an alias and is stripped from the resulting id.
 */
export function createAbliterationProvider(
  providerPath: string,
  providerOptions: ProviderOptions = {},
): AbliterationProvider {
  const splits = providerPath.split(':');
  let rest = splits.slice(1);

  // `chat` is an alias for the (only) chat completions modality; strip it.
  if (rest[0] === 'chat') {
    rest = rest.slice(1);
  }

  const modelName = rest.join(':');
  if (!modelName) {
    throw new Error(
      'Abliteration provider requires a model name. Use format: abliteration:<model_name> or abliteration:chat:<model_name>',
    );
  }

  return new AbliterationProvider(modelName, providerOptions);
}
