/**
 * Returns the first value that is neither undefined/null nor an empty string.
 * Empty strings are treated as unset so they fall through to the next candidate.
 */
function firstNonEmpty(...values: Array<string | undefined>): string | undefined {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== '') {
      return value;
    }
  }
  return undefined;
}

/**
 * Provider for the Abliteration AI service. Speaks the OpenAI-compatible
 * chat completions API but manages its own authentication and configuration
 * (it never falls back to OpenAI credentials or the OpenAI-Organization header).
