export class AbliterationProvider implements ApiProvider {
  modelName: string;
  config: AbliterationConfig;
  env?: EnvOverrides;

  constructor(modelName: string, options: ProviderOptions = {}) {
    const { config, env } = options;
    this.modelName = modelName;
    this.env = env;

    const providedConfig = (config ?? {}) as Partial<AbliterationConfig>;

    // Resolve the API base URL following the documented priority order:
    // (1) config.apiBaseUrl, (2) env override, (3) process env, (4) default.
    const apiBaseUrl =
      firstNonEmpty(
        providedConfig.apiBaseUrl,
        env?.ABLIT_API_BASE_URL,
        getEnvString('ABLIT_API_BASE_URL'),
      ) ?? ABLITERATION_API_BASE_URL;

    this.config = {
      ...providedConfig,
      apiBaseUrl,
      apiKeyEnvar: providedConfig.apiKeyEnvar || ABLITERATION_API_KEY_ENVAR,
      showThinking: providedConfig.showThinking ?? false,
    };
  }

  id(): string {
    return `abliteration:${this.modelName}`;
  }

  toString(): string {
    return `[Abliteration Provider ${this.modelName}]`;
  }

  toJSON() {
    return {
      provider: 'abliteration',
      model: this.modelName,
      config: {
        ...this.config,
        // Redact the API key from JSON output regardless of how it was provided.
        apiKey: undefined,
      },
    };
  }

  getApiKey(): string | undefined {
    const envar = this.config.apiKeyEnvar;
    return (
      this.config.apiKey ||
      this.env?.[envar as keyof EnvOverrides] ||
      getEnvString(envar as EnvVarKey)
    );
  }

  getOrganization(): undefined {
    return undefined;
  }

  private getMissingApiKeyErrorMessage(): string {
    return `API key is not set. Set the ${this.config.apiKeyEnvar} environment variable or add \`apiKey\` to the provider config.`;
